// ===========================================================================
// ACE website lead -> Kit. Kit is the system of record.
// Field keys and tag IDs below are LIVE production values. Do not guess here.
// ===========================================================================
const TAGS = {
  AUDIENCE_PROSPECT : 23084590, // AUDIENCE - ACE Prospect              (always)
  SOURCE_READINESS  : 23084591, // SOURCE - ACE Growth Readiness Check
  PROGRAM_BRIEF     : 23084592, // PROGRAM - ACE Weekly AI Brief   (opt-in ONLY)
  NO_CROSS_SEND     : 23084593, // DO NOT CROSS-SEND - ACE Commercial   (always)
  QUALIFIED_LEAD    : 23084594  // ACE - Qualified Lead
};

const body = $input.first().json.body || $input.first().json || {};
const email = String(body.email || '').trim().toLowerCase();
const first = String(body.first_name || '').trim();

if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) throw new Error('INVALID_EMAIL');

const DISPOSABLE = ['mailinator.com','guerrillamail.com','10minutemail.com',
                    'tempmail.com','trashmail.com','yopmail.com'];
if (DISPOSABLE.includes(email.split('@')[1])) throw new Error('DISPOSABLE_EMAIL');

// Completed the three diagnostic questions.
const completedCheck = !!(body.problem && body.urgency && body.ai_maturity);

// The Brief tag goes on ONLY where the visitor asked for the Brief by name.
// The hero field reads "Get the brief - Weekly. No noise." That is an opt-in.
// The diagnostic forms are not, and must never be treated as one.
const briefOptIn = body.brief_optin === true || body.form === 'brief';

const tags = [TAGS.AUDIENCE_PROSPECT, TAGS.NO_CROSS_SEND];
if (body.form === 'readiness' || completedCheck) tags.push(TAGS.SOURCE_READINESS);
if (completedCheck) tags.push(TAGS.QUALIFIED_LEAD);
if (briefOptIn) tags.push(TAGS.PROGRAM_BRIEF);

// ---------------------------------------------------------------------------
// Kit custom fields - LIVE KEYS ONLY, mapped from what the site collects:
//   problem     -> ace_biggest_bottleneck
//   ai_maturity -> ace_current_ai_use
// ace_business_type, ace_team_size and ace_90-day_outcome are not collected by
// this form, so they stay unset rather than being filled with a guess.
//
// RECORDED GAP: the form also collects urgency and constraint, and Kit has no
// field for either. They go to the alert instead of being forced into a field
// that means something else.
// ---------------------------------------------------------------------------
const fields = {};
if (body.problem)     fields['ace_biggest_bottleneck'] = String(body.problem).slice(0,200);
if (body.ai_maturity) fields['ace_current_ai_use']     = String(body.ai_maturity).slice(0,100);



// --- Notion CRM mapping ---------------------------------------------------
// The site's phrasing is not the CRM's option names. Map explicitly; an
// unmatched value becomes 'Unknown' rather than failing the whole write.
const URG = { 'urgent':'This quarter', 'quarter':'This quarter',
              '6 months':'Next 6 months', 'six months':'Next 6 months',
              'planning':'Planning ahead' };
const CON = { 'no time':'No time', 'no one':'No one to build it',
              'budget':'Budget', 'where to start':'Do not know where to start' };
function pick(map, raw, fallback){
  const s = String(raw||'').toLowerCase();
  for (const k in map) if (s.indexOf(k) !== -1) return map[k];
  return fallback;
}
const TAGNAME = {
  23084590:'AUDIENCE - ACE Prospect', 23084591:'SOURCE - Growth Readiness Check',
  23084592:'PROGRAM - Weekly AI Brief', 23084593:'DO NOT CROSS-SEND - Commercial',
  23084594:'ACE - Qualified Lead'
};

return [{ json: {
  email, first_name: first, fields, tags,
  notion_urgency:    pick(URG, body.urgency, 'Unknown'),
  notion_constraint: pick(CON, body.constraint, 'Unknown'),
  notion_source:     briefOptIn ? 'Website - Brief opt-in' : 'Website - Readiness Check',
  notion_tags:       tags.map(function(t){ return TAGNAME[t]; }).filter(Boolean),
  urgency:     String(body.urgency     || '').slice(0,100),
  constraint:  String(body.constraint  || '').slice(0,100),
  problem:     String(body.problem     || '').slice(0,200),
  ai_maturity: String(body.ai_maturity || '').slice(0,100),
  brief_optin: briefOptIn,
  qualified:   completedCheck,
  received_at: new Date().toISOString(),
  alert_to: 'AceGrowth.os@gmail.com'
}}];
